  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('BatchPrintPackToken','PrintRenderToken') AND (c.relrowsecurity OR c.relforcerowsecurity)) THEN RAISE EXCEPTION 'migration-only table unexpectedly has RLS state'; END IF;
  IF EXISTS (
    (SELECT tablename,policyname,cmd FROM pg_policies WHERE schemaname='public' EXCEPT SELECT * FROM (VALUES ('AuditLog','full_rls_auditlog_insert_sql_profile_audit_log_licen_94344ee5bf','INSERT'),('AuditLog','full_rls_auditlog_insert_sql_profile_audit_log_manuf_05e750c2a3','INSERT'),('AuditLog','full_rls_auditlog_insert_sql_profile_audit_log_platf_7acd564b55','INSERT'),('AuditLog','full_rls_auditlog_insert_sql_profile_risk_analytics__0f42474373','INSERT'),('AuditLog','full_rls_auditlog_insert_sql_profile_risk_analytics__fa8df9e7e5','INSERT'),('AuditLog','full_rls_auditlog_select_sql_profile_audit_log_licen_9fc3407041','SELECT'),('AuditLog','full_rls_auditlog_select_sql_profile_audit_log_manuf_76949345a1','SELECT'),('AuditLog','full_rls_auditlog_select_sql_profile_audit_log_platf_0a07cbe1e0','SELECT'),('AuditLog','full_rls_internal_platform_audit_details','SELECT'),('Batch','full_rls_batch_select_sql_profile_risk_analytics_lic_c1a48aed58','SELECT'),('Batch','full_rls_batch_select_sql_profile_risk_analytics_pla_5cb898fc84','SELECT'),('Incident','full_rls_incident_select_sql_profile_risk_analytics__5b7afba446','SELECT'),('Incident','full_rls_incident_select_sql_profile_risk_analytics__e0fb8de21b','SELECT'),('Licensee','full_rls_internal_manufacturer_licensee','SELECT'),('Licensee','full_rls_licensee_select_sql_profile_risk_analytics__14d7456070','SELECT'),('Licensee','full_rls_licensee_select_sql_profile_risk_analytics__196ec818f8','SELECT'),('ManufacturerLicenseeLink','full_rls_internal_manufacturer_link','SELECT'),('ManufacturerLicenseeLink','full_rls_manufacturerlicenseelink_select_sql_profile_23bfa2d5a1','SELECT'),('ManufacturerLicenseeLink','full_rls_manufacturerlicenseelink_select_sql_profile_f6bb844ebb','SELECT'),('Organization','full_rls_internal_manufacturer_org','SELECT'),('Organization','full_rls_organization_select_sql_profile_risk_analyt_287c51409b','SELECT'),('Organization','full_rls_organization_select_sql_profile_risk_analyt_e01a17d3ed','SELECT'),('Pol